pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 value1, uint256 blockNum1, uint256 time1, uint256 value2, uint256 blockNum2, uint256 time2) public {
        // Constrain temporal order: time1 < time2, blockNum1 < blockNum2
        vm.assume(time1 < time2);
        vm.assume(blockNum1 < blockNum2);

        // Deal the test contract some ether to cover both payments
        vm.deal(address(this), 30 ether);

        // --- First call ---
        vm.warp(time1);
        vm.roll(blockNum1);
        (bool ok1,) = address(c).call{value: value1}("");
        require(ok1, "first call failed"); // ensure we are within admissible domain

        // --- Second call ---
        vm.warp(time2);
        vm.roll(blockNum2);
        (bool ok2,) = address(c).call{value: value2}("");
        require(ok2, "second call failed");

        // The universal property: if the second call's value equals 10 ether, then either
        // 1) a transfer did NOT happen in the second call (blockNum2 % 15 != 0), OR
        // 2) a transfer DID happen AND the contract's final balance is exactly
        //    (value1 + value2) minus the balance after the first call's possible transfer.
        // We encode this by checking that after two calls, the contract does not end up
        // with a balance greater than zero when value2 == 0, which the mutant allows.
        // More precisely: if value2 < 10 ether, the contract MUST NOT reset pastBlockTime
        // and MUST NOT attempt a transfer. The reference reverts, but we wrap it.
        // However, we need a single assertion that holds for all inputs in P and breaks for M.
        // In P, any call with msg.value != 10 ether reverts, so state never changes.
        // In M, a zero-value call resets pastBlockTime and can trigger a drain.
        // Thus we assert: after two calls, the contract's balance is either 0 or it
        // comes exclusively from 10 ether payments that did not trigger a transfer.
        // Simpler: the invariant is that pastBlockTime only increases after a 10-ether call.
        bool invariantHolds = (c.pastBlockTime() == time2 ? value2 == 10 ether : true);
        assertTrue(invariantHolds);
    }
}

