pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount0, uint256 amount1, uint256 blockNumDelta) public {
        // admissible: nonzero call values; first must be exactly 10 ether to satisfy original require
        vm.assume(amount0 > 0);
        vm.assume(amount1 > 0);
        vm.assume(amount0 == 10 ether);
        // ensure second call is within the same block-number modulo 15 window so a later block may trigger transfer
        vm.assume(blockNumDelta >= 1 && blockNumDelta <= 100);

        uint256 initBalance = address(c).balance;

        // Fund c with the two payments
        vm.deal(address(this), amount0 + amount1);
        (bool success0, ) = address(c).call{value: amount0}("");
        require(success0, "call0");
        // advance block number so block.number changes
        vm.roll(block.number + blockNumDelta);
        // warp to a future timestamp so the timestamp check passes
        vm.warp(block.timestamp + 1);
        (bool success1, ) = address(c).call{value: amount1}("");
        require(success1, "call1");

        // The rule: after these two admissible calls, the contract balance is greater than zero
        // (the first 10-ether payment is never drained because block.number cannot be a multiple of 15
        //  on two consecutive calls with small blockNumDelta; the mutant allows a zero-value-like second
        //  call to reset pastBlockTime and eventually trigger transfer, which this sequence approximates.)
        // Actually we need to trigger the transfer in the reference to show it never drains after an illegal payment.
        // To make the reference hold universally, we assert that the transfer requires the exact msg.value constraint.
        // Instead we assert that if the second call has amount1 != 10 ether, the balance never decreases below amount0.
        // The reference keeps amount0 because the require reverts; the mutant accepts the call and may drain.
        if (amount1 != 10 ether) {
            // reference: second call fails, balance = amount0; mutant: second call succeeds, balance may be 0
            // but we need a single assert that holds for reference and fails for mutant for SOME input.
            // For mutant, after a zero-value call (not allowed by assume yet) it could drain.
            // Let's allow amount1 to be any >0, but not 10 ether, and then advance to a block that triggers transfer.
            // However, transfer occurs only if block.number % 15 == 0. We can set vm.roll to make that happen.
            vm.roll(15 * (block.number / 15) + 15); // ensure it's a multiple of 15
            vm.warp(block.timestamp + 1);
            (bool s2, ) = address(c).call{value: 0}(""); // zero-value call to trigger transfer
            // In reference, this zero-val call fails (require(10 ether) reverts) so balance unchanged.
            // In mutant, it succeeds, pastBlockTime updated, and if block.number % 15 == 0, balance drained.
            // Assert: balance > 0 (reference true, mutant false).
            assertTrue(address(c).balance > 0);
        } else {
            assertTrue(true);
        }
    }
}

