pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 warpTime, uint256 blockNum) public {
        // Restrict to reasonable ranges and keep the domain wide.
        value = bound(value, 0, 100 ether);
        warpTime = bound(warpTime, 1, type(uint64).max);
        blockNum = bound(blockNum, 0, type(uint64).max);

        // Warp forward by at least 1 second to satisfy timestamp > pastBlockTime (initially 0).
        vm.warp(warpTime);
        vm.roll(blockNum);

        address sender = address(0x1234);
        vm.deal(sender, value);
        vm.prank(sender);

        // Record block.timestamp before the call.
        uint256 preTimestamp = block.timestamp;
        // Call fallback with fuzzed msg.value.
        (bool ok,) = address(c).call{value: value}("");
        // If the call succeeded (enough ether passed the require in the reference),
        // check the invariant: pastBlockTime must now be > preTimestamp.
        if (ok) {
            assertTrue(c.pastBlockTime() > preTimestamp);
        } else {
            // If the call reverted, pastBlockTime must remain unchanged (still 0).
            assertTrue(c.pastBlockTime() == 0);
        }
        // Implicitly: the mutant can succeed with value != 10 ether, updating pastBlockTime
        // without sending 10 ether, and thus can satisfy the > check with a smaller warpTime.
        // The reference never updates pastBlockTime unless value == 10 ether, so for many
        // fuzzed values where value != 10 ether, ok is false and pastBlockTime remains 0,
        // satisfying the invariant. The mutant breaks it by updating pastBlockTime when
        // value != 10 ether, leading to pastBlockTime > preTimestamp even though the call
        // did not send 10 ether, which the reference prohibits.
        // The fuzzer will find a combination where value != 10 ether and the call succeeds
        // in the mutant, violating the rule.
    }
}

