contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber1, uint256 blockTimestamp1, uint256 blockNumber2, uint256 blockTimestamp2, uint256 timestampSame) public {
        // Limit values to plausible ranges to keep the domain wide but avoid overflow
        blockNumber1 = bound(blockNumber1, 0, 1000000);
        blockTimestamp1 = bound(blockTimestamp1, 1, 1000000);
        blockNumber2 = bound(blockNumber2, 0, 1000000);
        blockTimestamp2 = bound(blockTimestamp2, 1, 1000000);
        // We need a timestamp that equals the first call's timestamp to test the bug
        // Use the fuzzer-provided timestampSame and constrain it to the needed relationship
        vm.assume(timestampSame == blockTimestamp1);
        // Ensure the block number for the first call makes the transfer condition true (block.number % 15 == 0)
        vm.assume(blockNumber1 % 15 == 0);
        // Ensure the second call has a different block number (to independently control timestamp)
        vm.assume(blockNumber2 != blockNumber1);

        // Fund the caller
        address caller = makeAddr("caller");
        vm.deal(caller, 20 ether);

        // First call: set warp and roll, then execute fallback
        vm.warp(blockTimestamp1);
        vm.roll(blockNumber1);
        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        // Second call: reuse the same timestamp but potentially different block number
        vm.warp(timestampSame);
        vm.roll(blockNumber2);
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // For the reference C, ok2 must be false (the second call reverts because block.timestamp > pastBlockTime fails).
        // For the buggy M, ok2 may be true (the >= condition passes).
        assertTrue(!ok2, "Reference: second call must revert with same timestamp");
    }
}

