pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 ts, uint256 bn) public {
        // Restrict to a reasonable range and ensure block.number % 15 == 0 for both calls to trigger transfer.
        ts = bound(ts, 1, 2**32 - 1);
        bn = bound(bn, 15, 2**32 - 15);
        vm.assume(bn % 15 == 0);

        // First call:
        vm.roll(bn);
        vm.warp(ts);
        address sender1 = address(0x1000);
        vm.deal(sender1, 10 ether);
        vm.prank(sender1);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        bool firstOk = ok1;

        // Second call with same timestamp but different sender.
        // Transfer will be attempted if block.number % 15 == 0 (true) and timestamp condition holds.
        vm.roll(bn); // same block number
        vm.warp(ts); // same timestamp
        address sender2 = address(0x2000);
        vm.deal(sender2, 10 ether);
        vm.prank(sender2);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        bool secondOk = ok2;

        // Under the reference, the second call must fail (require >). Under the buggy version (>=), the second call succeeds.
        // Therefore, after both calls, the contract balance reveals the difference:
        // reference: second call reverts, so only 10 ether from first call was processed. The first call emptied the contract (transfer), so balance == 0.
        // buggy: second call succeeds and also transfers, so balance == 0 as well? Wait, we need a property that DIFFERS.
        // Let's refine: first call transfers (empties) → balance = 0. If second call succeeds, it adds 10 ether then transfers it → balance also 0.
        // Need a case where transfer does NOT happen on one of the calls. Let's make first call NOT trigger transfer, second call trigger transfer.
        // We need to make the buggy version allow a transfer when reference would not.

        // Re-adjust: make first call NOT divisible by 15 (so no transfer), second call divisible by 15. The reference reverts second call, buggy succeeds and transfers.
        vm.roll(bn - 1); // block number not divisible by 15
        vm.warp(ts);
        vm.prank(sender1);
        address(c).call{value: 10 ether}("");

        vm.roll(bn); // divisible by 15
        vm.warp(ts);
        vm.prank(sender2);
        (bool okBuggyScenario,) = address(c).call{value: 10 ether}("");

        // Reference: second call reverts, first call's 10 ether stays in contract. Balance == 10 ether.
        // Buggy: second call succeeds, transfers everything including the 10 ether from first call. Balance == 0.
        // So assert: if okBuggyScenario is false (reference), balance should be 10 ether; if true (buggy), balance is 0. But we need one assertion that holds for reference for ALL admissible inputs.
        // The reference satisfies: for any two calls where first does not transfer and second would transfer with same timestamp, the second call fails.
        // Property: after the second call, contract balance must be exactly 10 ether (since first call's ether wasn't transferred out, second call reverts).
        // Buggy version violates this because second call succeeds and transfers all, leaving balance 0.

        assertEq(address(c).balance, 10 ether, "Balance should be 10 ether because second call reverts in reference");
    }
}

