pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber1, uint256 blockNumber2) public {
        // Ensure admissible block numbers: first call not divisible by 15 (to avoid full drain),
        // second call divisible by 15 to trigger the transfer and expose the difference.
        vm.assume(blockNumber1 % 15 != 0);
        vm.assume(blockNumber2 != blockNumber1);
        vm.assume(blockNumber2 % 15 == 0);
        vm.assume(blockNumber1 > 0 && blockNumber2 > blockNumber1);

        address sender = address(0x1234);
        vm.deal(sender, 20 ether);

        // First call: warped to a block with number blockNumber1, timestamp = blockNumber1.
        vm.warp(blockNumber1);
        vm.roll(blockNumber1);
        vm.prank(sender);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        uint256 pastAfterFirst = c.pastBlockTime();

        // Second call: warped to a different block with number blockNumber2, timestamp = blockNumber2.
        vm.warp(blockNumber2);
        vm.roll(blockNumber2);
        vm.prank(sender);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");

        uint256 pastAfterSecond = c.pastBlockTime();

        // After the second call that triggers a transfer, the reference updates pastBlockTime
        // *before* the transfer, so pastBlockTime should be block.timestamp of the second call (blockNumber2).
        // The buggy version updates pastBlockTime *after* the transfer, so pastBlockTime remains the value
        // from the first call (pastAfterFirst = blockNumber1).
        assertTrue(pastAfterSecond == blockNumber2);
    }
}

