    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum1, uint256 blockNum2, uint256 timestamp1, uint256 timestamp2) public {
        // Ensure block numbers are positive and distinct for two calls
        vm.assume(blockNum1 > 0);
        vm.assume(blockNum2 > 0);
        vm.assume(blockNum2 > blockNum1);
