        // This keeps the scenario clean: first call just updates pastBlockTime, second call triggers transfer.
        vm.assume(blockNum1 % 15 != 0);

        address sender = makeAddr("sender");
        vm.deal(sender, 20 ether);

        // First call: set block number and timestamp, send 10 ether
        vm.roll(blockNum1);
        vm.warp(timestamp1);
        vm.prank(sender);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first call failed");

        // Second call: update block number and timestamp, send another 10 ether
        vm.roll(blockNum2);
        vm.warp(timestamp2);
        vm.prank(sender);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2, "second call failed");

        // After both calls, pastBlockTime must equal the timestamp of the second call
        // Reference updates pastBlockTime before transfer; buggy updates after, leaving it at timestamp1.
        assertTrue(c.pastBlockTime() == timestamp2);
    }
}

